let n=$('newTeam');if(n)n.onclick=()=>editTeam(null);let up=$('upgradeInstitute');if(up)up.onclick=()=>{let l=s.institute;if(l>=25||s.luz<l*100||s.mariri<l*50)return msg('Limite ou recursos insuficientes.');if(s.buildQueue)return msg('A fila de construção está ocupada.');s.luz-=l*100;s.mariri-=l*50;s.buildQueue={key:'institute',name:'Casa do Instituto',until:s.clock+Math.max(20,l*30),endsAt:Date.now()+Math.max(20,l*30)*1000};msg('🏛️ Evolução do Instituto iniciada.');save();render();return;s.institute++;s.enemies.filter(e=>e.active&&!s.teams.some(t=>t.target===e.id)).forEach(e=>{let newLevel=Math.max(1,s.institute+(e.id%7)-3);if(newLevel>e.level){let ratio=e.hp/e.max;e.level=newLevel;e.max=Math.round(FOES[e.type][3]*(0.35+newLevel/FOES[e.type][2]*0.65));e.hp=Math.round(e.max*ratio)}});msg('🏠 Instituto evoluiu para Nv.'+s.institute);save();render()};
