document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspect(s.enemies.find(e=>e.id===+b.dataset.inspect)));document.querySelectorAll('[data-retreat]').forEach(b=>b.onclick=()=>{let e=+b.dataset.retreat;let ids=s.selected.length?s.selected:s.teams.filter(t=>t.target===e).map(t=>t.id);ids.forEach(id=>{let t=s.teams.find(t=>t.id===id);if(t&&t.target===e){t.order='move';t.target=null;t.tx=HOME.x;t.ty=HOME.y}});save();render()});
